public extension PlanStepState {
    /// The marker of this state, as `PLAN_STATE_MARKERS` in `@adecore/plan` writes it.
    var marker: String {
        switch self {
        case .open: "[ ]"
        case .active: "[~]"
        case .done: "[x]"
        case .failed: "[!]"
        case .skipped: "[-]"
        case .blocked: "[?]"
        case .warning: "[w]"
        case .info: "[i]"
        }
    }
}
